import {researchQuestions} from './research-data.js';
export {researchQuestions};
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct = value => (value * 100).toFixed(2);
const metric = (q, d) => q.metric.reduce((sum, key) => sum + d[key], 0);
const note = q => `<p class="research-note">${esc(q.model)} · 과거 설문 응답자 1,200명 기반 · 선택 확률 평균<br>실제 여론조사 아님 · 예측 오차 미산출 · 전국 대표성 미검증</p>`;
function distribution(options, dist) {
  return `<div class="research-distribution">${Object.entries(options).map(([key,label]) => `<div class="distribution-row"><span>${esc(label)}</span><strong>${pct(dist[key])}%</strong><div class="distribution-track"><span style="width:${dist[key]*100}%"></span></div></div>`).join('')}</div>`;
}
export function researchCard(q, saved) {
  const c = q.conditions[q.defaultCondition];
  return `<article class="question-card research-card"><div class="market-card-heading"><span class="tag">실행된 시뮬레이션</span><button class="bookmark ${saved?'saved':''}" data-action="save" data-id="${q.id}" aria-label="${esc(q.title)} 저장" aria-pressed="${saved}">${saved?'★':'☆'}</button></div><h3><a href="#/result/${q.id}">${esc(q.title)}</a></h3><p class="micro">${q.id==='parent-support-70'?'부모가 집값 70%를 지원한다면':'주 40시간 근무 · 소득 조건 3가지'}</p><div class="research-card-value"><span>${esc(q.metricLabel)}${q.id==='housework-income-30'?' · 소득 동일':''}</span><strong>${(metric(q,c.dist)*100).toFixed(1)}<small>%</small></strong></div>${note(q)}<div class="question-footer"><span>${esc(q.experiment)}</span><a class="join" href="#/result/${q.id}">결과 자세히 보기 →</a></div></article>`;
}
export function researchContent(q, selected, vote, saved) {
  const arm = q.conditions[selected] ? selected : q.defaultCondition, c = q.conditions[arm];
  const multi = Object.keys(q.conditions).length > 1;
  return `<a class="text-button back-link" href="#/">← 질문 둘러보기</a><div class="result-heading"><div class="pill-row"><span class="tag">실행된 시뮬레이션</span><span class="demo-pill">${q.experiment} · 2026.09.14</span></div><h1>${esc(q.title)}</h1><p>${q.id==='parent-support-70'?'집값 지원이 거주 지역 선택에도 영향을 줄까?':'둘 다 주 40시간 일한다면, 소득 차이는 가사 분담에 영향을 줄까?'}</p></div><div class="result-layout"><div class="result-main"><section class="panel">
  ${multi?`<div class="research-tabs" role="group" aria-label="소득 조건">${Object.entries(q.conditions).map(([key,condition])=>`<button data-action="research-condition" data-id="${q.id}" data-value="${key}" aria-pressed="${key===arm}">${esc(condition.label)}</button>`).join('')}</div>`:''}
  <p class="research-condition">${esc(c.description)}</p><details class="research-context"><summary>질문의 전제와 정확한 문구</summary><p>${esc(q.context)}</p><p><strong>${esc(q.question)}</strong></p></details>
  <div class="research-headline"><span>${esc(q.metricLabel)}</span><strong>${(metric(q,c.dist)*100).toFixed(2)}<small>%</small></strong>${c.delta!=null?`<span class="research-delta">동일 소득보다 ${Math.abs(c.delta).toFixed(2)}%p ${c.delta<0?'낮음':'높음'}</span>`:''}</div>${note(q)}
  <h2 class="research-subheading">전체 응답</h2>${multi?'<p class="micro">선택지의 가사 비율은 남편 A가 맡는 몫입니다.</p>':''}${distribution(q.options,c.dist)}<p class="micro">각 선택지를 고를 확률의 평균입니다. 실제 투표수나 평균 가사 분담 비율이 아니며, 반올림으로 합계가 100%와 다를 수 있습니다.</p></section>
  ${multi?`<section class="panel"><h2>소득이 달라지면, 반반 분담은?</h2><div class="condition-comparison">${Object.entries(q.conditions).map(([key,condition])=>`<div><span>${esc(condition.label)}</span><strong>${pct(condition.dist.P50)}%</strong><small>${key==='E'?'기준':`동일 소득 대비 ${condition.delta.toFixed(2)}%p`}</small></div>`).join('')}</div><p class="research-note">GPT-5.5 · 조건마다 같은 1,200명 · 반반 선택 확률 평균<br>같은 인물의 조건별 확률 차이를 평균했습니다. 실제 국민의 인과효과와 반복 안정성은 미검증입니다.</p></section>`:''}
  <details class="panel detail-panel"><summary>세대·성별로는 얼마나 다를까?</summary><p class="body-muted">현재 조건: ${esc(c.label)} · ${esc(q.metricLabel)} 선택 확률</p><div class="research-group-list">${c.groups.map(g=>`<div><span>${esc(g.label)} <small>${g.n}명</small></span><strong>${(metric(q,g.dist)*100).toFixed(2)}%</strong></div>`).join('')}</div>${note(q)}<details class="research-context"><summary>집단별 여섯 선택지 모두 보기</summary><div class="research-table-wrap" tabindex="0" role="region" aria-label="집단별 전체 응답 표"><table class="research-table"><thead><tr><th>집단</th><th>인원</th>${Object.values(q.options).map(l=>`<th>${esc(l)}</th>`).join('')}</tr></thead><tbody>${c.groups.map(g=>`<tr><th>${esc(g.label)}</th><td>${g.n}</td>${Object.keys(q.options).map(k=>`<td>${pct(g.dist[k])}%</td>`).join('')}</tr>`).join('')}</tbody></table></div></details><p class="micro">연령과 성별은 설문 응답자의 조사 당시 정보입니다. 소집단 차이는 기술 통계이며 집단별 예측 오차는 미산출입니다.</p></details>
  <section class="panel"><h2>당신은 어떻게 생각하나요?</h2><p class="body-muted">${esc(c.label)} 조건에서 ${multi?'남편 A가 맡을 가사 비율을':'내 의견을'} 골라보세요.</p><div class="research-votes">${Object.entries(q.options).map(([key,label])=>`<button class="vote-button ${vote===key?'selected':''}" data-action="research-vote" data-id="${q.id}" data-condition="${arm}" data-value="${key}" aria-pressed="${vote===key}">${esc(label)}</button>`).join('')}</div><p class="micro">${vote?'이 기기에서 선택한 의견입니다. 다른 선택지로 변경할 수 있어요.':'선택은 이 브라우저에만 저장돼요.'} 실제 방문자 투표 집계는 아직 연결되지 않았습니다.</p></section>
  ${q.previous?`<details class="panel detail-panel"><summary>이전 실험 보기 · 성별을 지정하지 않은 부부 A·B</summary><p>${esc(q.previous.context)}</p><p><strong>${esc(q.previous.question)}</strong></p>${distribution(q.previous.options,q.previous.dist)}<p class="research-note">${esc(q.previous.model)} · ${q.previous.experiment} · 1,200명 · 선택 확률 평균<br>모델과 성별 조건이 달라 위 결과와의 차이를 소득 효과로 비교할 수 없습니다. 실제 여론조사 아님 · 예측 오차 미산출 · 전국 대표성 미검증</p></details>`:''}
  <details class="panel detail-panel"><summary>데이터와 해석 범위</summary><dl class="evidence-list"><div><dt>실행 모델</dt><dd>${esc(q.model)} · ${q.experiment} · 불변 스냅샷 미확보</dd></div><div><dt>기반 자료</dt><dd>2018·2021·2023·2025년 실제 설문 응답자 각 300명, 개인별 상세 응답 214~361개</dd></div><div><dt>집계 방식</dt><dd>인물마다 최초 유효 응답의 확률 분포를 동일 비중으로 평균. 현재 대한민국 인구를 대표하도록 가중한 결과가 아닙니다.</dd></div><div><dt>검증 상태</dt><dd>실행·집계 정합성 확인. 인간 응답 정확도·전국 대표성·반복 안정성 미검증, 예측 오차 구간 미산출.</dd></div><div><dt>선택 이유</dt><dd>이번 실험에서는 이유와 개인 의견 문장을 수집하지 않았습니다.</dd></div></dl><p class="micro">일반 질문을 즉시 처리하는 엔진은 아직 연결되지 않았습니다. 이 화면은 완료된 실험의 집계 결과를 제공합니다.</p></details></div><div class="result-actions"><button class="secondary" data-action="copy-link" data-id="${q.id}">질문 링크 복사</button><button class="secondary" data-action="save" data-id="${q.id}" aria-pressed="${saved}">${saved?'★ 저장됨':'☆ 저장'}</button><a class="primary" href="#/result/${q.id==='parent-support-70'?'housework-income-30':'parent-support-70'}">다른 실험 결과 보기 →</a></div></div>`;
}
